// Estimates, deliberately editable: variable-tempo grids are not inferred.
export function analysePCM(samples,sampleRate=11025){
 const hop=256,count=Math.floor(samples.length/hop);if(count<20)return {bpm:120,bpmConfidence:0,gridOffset:0,key:'—',keyConfidence:0};
 const envelope=new Float32Array(count);let lp=0,previous=0;for(let f=0;f<count;f++){let e=0;for(let j=0;j<hop;j++){lp+=(samples[f*hop+j]-lp)*.12;e+=lp*lp;}const rms=Math.sqrt(e/hop);envelope[f]=Math.max(0,rms-previous*.92);previous=rms;}
 let bestBpm=120,best=0;const fps=sampleRate/hop;for(let bpm=65;bpm<=180;bpm+=.25){const lag=60*fps/bpm;let s=0,w=0;for(let i=Math.ceil(lag*2);i<count;i++){let a=i-lag,j=Math.floor(a),v=envelope[j]*(1-(a-j))+envelope[j+1]*(a-j);s+=envelope[i]*v;w+=envelope[i]*envelope[i];}s=s/(w||1);s*=1-.07*Math.abs(Math.log2(bpm/125));if(s>best){best=s;bestBpm=bpm;}}
 // Interpolated autocorrelation alone has maxima at integer frame lags.
 // Refine tempo by regressing detected onset times against coarse beat indices.
 let maxOnset=0;for(const x of envelope)maxOnset=Math.max(maxOnset,x);const onsets=[];for(let i=1;i<count-1;i++){const v=envelope[i];if(v<maxOnset*.28||v<envelope[i-1]||v<envelope[i+1])continue;const den=envelope[i-1]-2*v+envelope[i+1],delta=den?Math.max(-.5,Math.min(.5,.5*(envelope[i-1]-envelope[i+1])/den)):0;const t=(i+delta)/fps;if(!onsets.length||t-onsets.at(-1)>.22)onsets.push(t);}
 if(onsets.length>5){const period=60/bestBpm,origin=onsets[0],points=[];let beatIndex=0;for(let i=0;i<onsets.length;i++){if(i)beatIndex+=Math.max(1,Math.round((onsets[i]-onsets[i-1])/period));points.push([beatIndex,onsets[i]]);}const mx=points.reduce((s,p)=>s+p[0],0)/points.length,my=points.reduce((s,p)=>s+p[1],0)/points.length;let cov=0,varx=0;for(const[x,y]of points){cov+=(x-mx)*(y-my);varx+=(x-mx)**2;}const refinedPeriod=cov/varx,refined=60/refinedPeriod,intercept=my-refinedPeriod*mx,residual=points.reduce((s,[x,y])=>s+(y-intercept-refinedPeriod*x)**2,0)/points.length;if(Number.isFinite(refined)&&Math.abs(refined-bestBpm)/bestBpm<.045&&Math.sqrt(residual)<period*.13)bestBpm=refined;}
 const beat=60/bestBpm;let phase=0,phaseScore=-1;for(let p=0;p<beat;p+=1/fps){let s=0;for(let t=p;t<Math.min(60,samples.length/sampleRate);t+=beat){const i=Math.round(t*fps);s+=(envelope[i]||0)+.4*(envelope[i-1]||0)+.4*(envelope[i+1]||0);}if(s>phaseScore){phaseScore=s;phase=p;}}
 // Coarse constant-Q chroma via Goertzel over spaced windows.
 const chroma=new Float64Array(12),window=4096,nSegments=Math.min(24,Math.floor(samples.length/window));for(let seg=0;seg<nSegments;seg++){let start=Math.floor((samples.length-window)*seg/Math.max(1,nSegments-1));for(let midi=45;midi<=83;midi++){const freq=440*Math.pow(2,(midi-69)/12),co=2*Math.cos(2*Math.PI*freq/sampleRate);let a=0,b=0;for(let i=0;i<window;i++){const v=samples[start+i]*(.5-.5*Math.cos(2*Math.PI*i/window));const c=v+co*a-b;b=a;a=c;}const power=Math.max(0,a*a+b*b-co*a*b);chroma[midi%12]+=Math.sqrt(power);}}
 const major=[6.35,2.23,3.48,2.33,4.38,4.09,2.52,5.19,2.39,3.66,2.29,2.88],minor=[6.33,2.68,3.52,5.38,2.6,3.53,2.54,4.75,3.98,2.69,3.34,3.17];const names=['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'];let key='—',keyScore=-Infinity,second=-Infinity;
 const correlate=(p,r)=>{let ma=chroma.reduce((a,b)=>a+b,0)/12,mb=p.reduce((a,b)=>a+b,0)/12,x=0,y=0,z=0;for(let i=0;i<12;i++){let a=chroma[(i+r)%12]-ma,b=p[i]-mb;x+=a*b;y+=a*a;z+=b*b;}return x/Math.sqrt(y*z||1);};
 for(let r=0;r<12;r++)for(const [profile,suffix] of [[major,''],[minor,'m']]){let score=correlate(profile,r);if(score>keyScore){second=keyScore;keyScore=score;key=names[r]+suffix;}else second=Math.max(second,score);}
 return {bpm:Math.round(bestBpm*10)/10,bpmConfidence:Math.round(Math.min(1,best)*100),gridOffset:Math.round(phase*1000)/1000,key:keyScore>.35?key:'—',keyConfidence:Math.round(Math.max(0,keyScore-second)*100)};
}
if(typeof self!=='undefined'&&typeof document==='undefined'&&typeof self.postMessage==='function')self.onmessage=e=>{try{self.postMessage({id:e.data.id,result:analysePCM(e.data.samples,e.data.sampleRate)});}catch(error){self.postMessage({id:e.data.id,error:error.message});}};
